input.command:
cat > .slop.json <<'E'
{
  "overrides": [
    { "files": ["README.md"], "ignore": ["chatbot"] },
    { "files": ["docs/de/**/*.md", "docs/fr/**/*.md"], "ignore": ["dash", "title-case-heading"] }
  ]
}
E
npm run lint:prose 2>&1 | grep -v "^$"; echo "exit ${PIPESTATUS[0]}"
printf 'This is a testament to our seamless work.\n' > docs/bad.md; npm run lint:prose >/dev/null 2>&1; echo bad-exit $?; rm docs/bad.md
printf 'Intro — text.\n' > docs/fr/new.md; npm run lint:prose >/dev/null 2>&1; echo fr-new $?; rm docs/fr/new.md
printf 'A fine line.\n' > docs/ok.md; npm run lint:prose >/dev/null 2>&1; echo ok-exit $?; rm docs/ok.md; npm test | tail -1

